class CircuitOpenError extends Error {
  constructor() {
    super('circuit open: failing fast');
    this.code = 'CIRCUIT_OPEN';
  }
}

class CircuitBreaker {
  constructor({ failureThreshold = 5, cooldownMs = 10000, clock }) {
    this.failureThreshold = failureThreshold;
    this.cooldownMs = cooldownMs;
    this.clock = clock;
    this.state = 'CLOSED';
    this.failures = 0;       // consecutive failures while CLOSED
    this.openedAt = 0;
    this.trialInFlight = false;
  }

  async call(fn) {
    if (this.state === 'OPEN') {
      if (this.clock.now() - this.openedAt < this.cooldownMs) throw new CircuitOpenError();
      this.state = 'HALF_OPEN';
    }
    if (this.state === 'HALF_OPEN') {
      if (this.trialInFlight) throw new CircuitOpenError();
      this.trialInFlight = true;
      try {
        const result = await fn();
        this.state = 'CLOSED';
        this.failures = 0;
        return result;
      } catch (err) {
        this.trip();
        throw err;
      } finally {
        this.trialInFlight = false;
      }
    }
    // CLOSED
    try {
      const result = await fn();
      this.failures = 0;
      return result;
    } catch (err) {
      this.failures++;
      if (this.failures >= this.failureThreshold) this.trip();
      throw err;
    }
  }

  trip() {
    this.state = 'OPEN';
    this.openedAt = this.clock.now();
    this.failures = 0;
  }
}

