let t = 0; const clock = { now: () => t };
const cb = new CircuitBreaker({ failureThreshold: 3, cooldownMs: 5000, clock });
let calls = 0;
const ok = async () => { calls++; return 'audio.mp3'; };
const boom = async () => { calls++; throw new Error('tts timeout'); };
const attempt = async (fn) => { try { return await fn(); } catch (e) { return e; } };
assertEqual(await cb.call(ok), 'audio.mp3');
const err = new Error('bad voice id');
const got = await attempt(() => cb.call(async () => { throw err; }));
assert(got === err, 'the original error object must be rethrown');
assertEqual(cb.state, 'CLOSED');

let t = 0; const clock = { now: () => t };
const cb = new CircuitBreaker({ failureThreshold: 3, cooldownMs: 5000, clock });
let calls = 0;
const ok = async () => { calls++; return 'audio.mp3'; };
const boom = async () => { calls++; throw new Error('tts timeout'); };
const attempt = async (fn) => { try { return await fn(); } catch (e) { return e; } };
for (let i = 0; i < 3; i++) await attempt(() => cb.call(boom));
assertEqual(cb.state, 'OPEN');
assertEqual(calls, 3);
const e = await attempt(() => cb.call(ok));
assertEqual(e && e.code, 'CIRCUIT_OPEN');
assertEqual(calls, 3, 'fn must not be called while open');

