let t = 0; const clock = { now: () => t };
const cb = new CircuitBreaker({ failureThreshold: 3, cooldownMs: 5000, clock });
let calls = 0;
const ok = async () => { calls++; return 'audio.mp3'; };
const boom = async () => { calls++; throw new Error('tts timeout'); };
const attempt = async (fn) => { try { return await fn(); } catch (e) { return e; } };
for (let i = 0; i < 3; i++) await attempt(() => cb.call(boom));
t = 5000;
let release;
const slow = () => { calls++; return new Promise((r) => { release = r; }); };
const trial = cb.call(slow);
assertEqual(cb.state, 'HALF_OPEN');
const second = await attempt(() => cb.call(ok));
assertEqual(second && second.code, 'CIRCUIT_OPEN', 'second caller must fail fast during the trial');
assertEqual(calls, 4, 'only the trial reached the vendor');
release('ok');
assertEqual(await trial, 'ok');
assertEqual(cb.state, 'CLOSED');
